package com.fakelegacy.order.aop;

import java.math.BigDecimal;
import java.time.LocalDateTime;

import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import com.fakelegacy.order.client.CatalogClient;
import com.fakelegacy.order.client.CustomerSnapshot;
import com.fakelegacy.order.client.RemoteResult;
import com.fakelegacy.order.client.RemoteServiceException;
import com.fakelegacy.order.domain.Order;
import com.fakelegacy.order.repo.OrderRepository;

/** Orders above 1000 EUR from accounts younger than 30 days wait for a manual review. */
@Aspect
@Component
public class FraudCheckAspect {

    private static final Logger log = LoggerFactory.getLogger(FraudCheckAspect.class);
    private static final BigDecimal THRESHOLD = new BigDecimal("1000");

    @Autowired
    private OrderRepository orders;

    @Autowired
    private CatalogClient catalog;

    @Value("${reservation.review-ttl-minutes:1440}")
    private int reviewTtlMinutes;

    @Around("execution(* com.fakelegacy.order.service.OrderManager.checkout(..))")
    public Object checkFraud(ProceedingJoinPoint pjp) throws Throwable {
        Object result = pjp.proceed();
        Order order = (Order) result;

        CustomerSnapshot customer = null;
        for (Object arg : pjp.getArgs()) {
            if (arg instanceof CustomerSnapshot c) {
                customer = c;
            }
        }
        if (customer == null || order.getTotalTtc().compareTo(THRESHOLD) <= 0
                || !customer.getRegisteredAt().isAfter(LocalDateTime.now().minusDays(30))) {
            return order;
        }

        order.setStatus("PENDING_REVIEW");
        // re-reserving the same reference extends the hold; if it fails the order keeps the short expiry
        try {
            RemoteResult r = catalog.reserve(order.getReference(), null, reviewTtlMinutes);
            if (r.isOk()) {
                order.setExpiresAt(LocalDateTime.now().plusMinutes(reviewTtlMinutes));
            } else {
                log.warn("could not extend reservation of {}: {}", order.getReference(), r.getMessage());
            }
        } catch (RemoteServiceException e) {
            log.warn("could not extend reservation of {}: {}", order.getReference(), e.getMessage());
        }
        return orders.save(order);
    }
}
